```js
export function resolveBrickHit(ball, bricks, onDestroy) {
  // ---- Phase 1: overlapping hits (ball currently inside a brick) ----
  let minPenX = Infinity, minPenY = Infinity;
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  let overlapHit = false;

  for (const brick of bricks) {
    if (!brick.alive) continue;
    if (!collides(ball, brick)) continue;
    overlapHit = true;
    brick.alive = false;
    if (onDestroy) onDestroy(brick);

    if (brick.x < minX) minX = brick.x;
    if (brick.x + brick.w > maxX) maxX = brick.x + brick.w;
    if (brick.y < minY) minY = brick.y;
    if (brick.y + brick.h > maxY) maxY = brick.y + brick.h;

    const penX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
    const penY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));
    if (penX < minPenX) minPenX = penX;
    if (penY < minPenY) minPenY = penY;
  }

  if (overlapHit) {
    // single bounce
    if (minPenX < minPenY) {
      ball.vx = -ball.vx;
      if (ball.vx > 0) ball.x = maxX + ball.r; else ball.x = minX - ball.r;
    } else if (minPenY < minPenX) {
      ball.vy = -ball.vy;
      if (ball.vy > 0) ball.y = maxY + ball.r; else ball.y = minY - ball.r;
    } else {
      ball.vx = -ball.vx; ball.vy = -ball.vy;
      if (ball.vx > 0) ball.x = maxX + ball.r; else ball.x = minX - ball.r;
      if (ball.vy > 0) ball.y = maxY + ball.r; else ball.y = minY - ball.r;
    }
    return true;
  }

  // ---- Phase 2: swept hits (tunnelling — ball jumped over a brick) ----
  const px = ball.prevX ?? ball.x;
  const py = ball.prevY ?? ball.y;
  let earliest = Infinity;
  let hitAxis = -1;
  let bestBrick = null;

  for (const brick of bricks) {
    if (!brick.alive) continue;
    const entry = segmentRectEntry(px, py, ball.x, ball.y,
      brick.x - ball.r, brick.y - ball.r,
      BRICK_W + ball.r*2, brick.h + ball.r*2);
    if (entry && entry.t < earliest) {
      earliest = entry.t;
      hitAxis = entry.axis;
      bestBrick = brick;
    }
  }

  if (bestBrick) {
    bestBrick.alive = false;
    if (onDestroy) onDestroy(bestBrick);
    // Place ball at the entry contact point.
    const cx = px + (ball.x - px) * earliest;
    const cy = py + (ball.y - py) * earliest;
    if (hitAxis === 0) {
      ball.vx = -ball.vx;
      ball.x = cx; 
      // push out along x
      if (ball.vx > 0) ball.x = ball.x + ball.r + 1; else ball.x = ball.x - ball.r - 1;
    } else {
      ball.vy = -ball.vy;
      ball.y = cy;
      if (ball.vy > 0) ball.y = cy + ball.r + 1; else ball.y = cy - ball.r - 1;
    }
    // leave y when x-axis bounce (ball.y = cy already fine)
    return true;
  }

  return false;
}
```

