} from './neon.js';

edits.newText:
test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

test('resolveBrickHit: brick removed and ball destroyed bricks => brick dead', () => {
  const brick = { x: 90, y: 90, w: 40, h: 20, alive: true };
  const ball = { x: 100, y: 100, r: 7, vx: 0, vy: 0 };
  const bounced = resolveBrickHit(ball, [brick]);
  assert.equal(bounced, true, 'a hit must report a bounce');
  assert.equal(brick.alive, false, 'the brick must be destroyed');
});

// --- #1 bounce cases: per-face, corner, push-out, neighbours, tunnelling ---

test('resolveBrickHit: top-face hit bounces vy and pushes the ball out', () => {
  const brick = { x: 90, y: 90, w: 72, h: 20, alive: true };
  // Ball moving up (negative vy), slightly overlapped at the brick bottom.
  const ball = { x: 120, y: 113, r: 7, vx: 0, vy: -300, prevX: 120, prevY: 125 };
  const bounced = resolveBrickHit(ball, [brick]);
  assert.equal(bounced, true);
  assert.ok(ball.vy < 0, 'vy should be flipped to UP after a top/bottom hit');
  assert.ok(ball.y + ball.r <= brick.y + brick.h, 'ball pushed clear below the brick');
});

test('resolveBrickHit: side-face hit bounces vx and pushes the ball out', () => {
  const brick = { x: 90, y: 90, w: 40, h: 80, alive: true };
  // Ball moving left into the brick right face.
  const ball = { x: 103, y: 120, r: 7, vx: -300, vy: 0, prevX: 110, prevY: 120 };
  const bounced = resolveBrickHit(ball, [brick]);
  assert.equal(bounced, true);
  assert.ok(ball.vx > 0, 'vx should be flipped to RIGHT after a side hit');
  assert.ok(ball.x - ball.r >= brick.x + brick.w, 'ball pushed clear right of the brick');
});

test('resolveBrickHit: corner (equal penetration) bounces both axes', () => {
  const brick = { x: 90, y: 90, w: 40, h: 20, alive: true };
  // Ball sits exactly on the brick corner: equal penetration on both axes.
  const ball = { x: 92.5, y: 96.5, r: 7, vx: -300, vy: -300, prevX: 92.5, prevY: 96.5 };
  const bounced = resolveBrickHit(ball, [brick]);
  assert.equal(bounced, true);
  assert.ok(ball.vx > 0, 'side component flipped by a corner hit');
  assert.ok(ball.vy < 0, 'vertical component flipped by a corner hit');
});

test('resolveBrickHit: two overlapping bricks bounce exactly once (neighbours)', () => {
  const b1 = { x: 90, y: 90, w: 72, h: 20, alive: true };
  const b2 = { x: 162, y: 90, w: 72, h: 20, alive: true };
  // Ball overlapping the seam between two bricks, moving down onto them.
  const ball = { x: 135, y: 110, r: 7, vx: 0, vy: 0 }; // stationary, vy flipped to -|vy|
  ball.vy = 300;
  const bounced = resolveBrickHit(ball, [b1, b2]);
  assert.equal(bounced, true);
  assert.equal(ball.vy, -300, 'vy flipped exactly once (two bricks must not re-flip it)');
  assert.equal(b1.alive, false);
  assert.equal(b2.alive, false);
});

test('resolveBrickHit: after push-out the ball no longer overlaps the bricks', () => {
  const brick = { x: 90, y: 90, w: 72, h: 20, alive: true };
  const ball = { x: 120, y: 113, r: 7, vx: 0, vy: -300, prevX: 120, prevY: 125 };
  resolveBrickHit(ball, [brick]);
  assert.equal(collides(ball, brick), false, 'ball pushed clear of the brick');
});

test('resolveBrickHit: fast-moving ball tunnels through a brick (swept hit)', () => {
  // Ball jumps from far above the brick to far below it in one step.
  const brick = { x: 90, y: 90, w: 72, h: 20, alive: true };
  const ball = { x: 120, y: 30, r: 7, vx: 0, vy: 900, prevX: 120, prevY: 30 };
  ball.y = 200; // simulated huge dt: previous pos (30) far above, current (200) far below
  const bounced = resolveBrickHit(ball, [brick]);
  assert.equal(bounced, true, 'a swept brick must still be detected');
  assert.equal(brick.alive, false);
  assert.ok(ball.vy < 0, 'ball must bounce back up after tunnelling through');
});

