  // Two bricks stacked vertically (8 px gap): a ball can overlap BOTH in one
  // frame. The bounce must be applied exactly once, not once per brick
  // (double-flipping vy would cancel out and let the ball through).
  const b1 = { x: 90, y: 90, w: 190, h: 20, alive: true };
